select jsonb_build_object(
 'captured_at', now(), 'database', current_database(), 'reader', current_user,
 'schemas', (select jsonb_agg(jsonb_build_object('name', nspname, 'owner', pg_get_userbyid(nspowner))) from pg_namespace where nspname !~ '^pg_' and nspname <> 'information_schema'),
 'relations', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'name', c.relname, 'kind', c.relkind, 'rls_enabled', c.relrowsecurity, 'rls_forced', c.relforcerowsecurity, 'owner', pg_get_userbyid(c.relowner), 'acl', c.relacl::text)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname <> 'information_schema' and c.relkind in ('r','p','v','m','S','f')),
 'columns', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'table', c.relname, 'name', a.attname, 'position', a.attnum, 'type', format_type(a.atttypid,a.atttypmod), 'not_null', a.attnotnull, 'identity', a.attidentity, 'generated', a.attgenerated, 'default', pg_get_expr(d.adbin,d.adrelid))) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attnum>0 and not a.attisdropped and n.nspname !~ '^pg_' and n.nspname <> 'information_schema' and c.relkind in ('r','p','v','m','f')),
 'constraints', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'table', c.relname, 'name', co.conname, 'definition', pg_get_constraintdef(co.oid))) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname <> 'information_schema'),
 'policies', (select jsonb_agg(to_jsonb(p)) from pg_policies p),
 'triggers', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'table', c.relname, 'name', t.tgname, 'enabled', t.tgenabled, 'definition', pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname !~ '^pg_' and n.nspname <> 'information_schema'),
 'functions', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'name', p.proname, 'identity_arguments', pg_get_function_identity_arguments(p.oid), 'security_definer', p.prosecdef, 'owner', pg_get_userbyid(p.proowner), 'config', p.proconfig, 'acl', p.proacl::text, 'definition', pg_get_functiondef(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','extensions') and p.prokind in ('f','p') and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'views', (select jsonb_agg(to_jsonb(v)) from pg_views v where v.schemaname !~ '^pg_' and v.schemaname <> 'information_schema'),
 'indexes', (select jsonb_agg(to_jsonb(i)) from pg_indexes i where i.schemaname !~ '^pg_' and i.schemaname <> 'information_schema'),
 'table_grants', (select jsonb_agg(to_jsonb(g)) from information_schema.table_privileges g where g.table_schema !~ '^pg_' and g.table_schema <> 'information_schema'),
 'column_grants', (select jsonb_agg(to_jsonb(g)) from information_schema.column_privileges g where g.table_schema !~ '^pg_' and g.table_schema <> 'information_schema'),
 'default_acls', (select jsonb_agg(jsonb_build_object('owner', pg_get_userbyid(d.defaclrole), 'schema', n.nspname, 'type', d.defaclobjtype, 'acl', d.defaclacl::text)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace)
) as catalog;
